1	//! The delimiter scans that carve a URL string into its components.
2	//!
3	//! Every function here is a pure lexical split returning borrowed slices, in
4	//! the same order the C++ constructor applies them. That order is observable:
5	//! because the fragment is removed before the scheme is looked for, a `"://"`
6	//! sitting inside a fragment or query never produces a scheme.
7	//!
8	//! All delimiters are ASCII, so the returned byte offsets always land on UTF-8
9	//! character boundaries.
10	
11	/// Splits the fragment at the **first** `'#'`, returning `(remainder, fragment)`.
12	///
13	/// Later `'#'` and `'?'` characters stay inside the fragment.
14	pub fn split_fragment(input: &str) -> (&str, &str) {
15	    match input.find('#') {
16	        Some(at) => (&input[..at], &input[at + 1..]),
17	        None => (input, ""),
18	    }
19	}
20	
21	/// Splits the query at the **first** `'?'`, returning `(remainder, query)`.
22	///
23	/// Runs after [`split_fragment`], so it only ever sees the pre-fragment text.
24	pub fn split_query(input: &str) -> (&str, &str) {
25	    match input.find('?') {
26	        Some(at) => (&input[..at], &input[at + 1..]),
27	        None => (input, ""),
28	    }
29	}
30	
31	/// Splits on the first `"://"`, returning `(raw_scheme, remainder)`.
32	///
33	/// Returns `None` when the separator is absent, which is what makes a bare
34	/// `"http:example.com"` parse as a path rather than a scheme. Note that no
35	/// grammar check is applied to the scheme text: `"1http"`, `"ht tp"` and `"/a"`
36	/// are all accepted verbatim, exactly as the C++ version accepts them.
37	pub fn split_scheme(input: &str) -> Option<(&str, &str)> {
38	    input
39	        .find("://")
40	        .map(|at| (&input[..at], &input[at + 3..]))
41	}
42	
43	/// Splits the post-`"://"` text into `(raw_authority, path)` at the first `'/'`.
44	///
45	/// The `'/'` itself belongs to the path, and an absent `'/'` yields an empty
46	/// path rather than an empty authority.
47	pub fn split_authority_and_path(input: &str) -> (&str, &str) {
48	    match input.find('/') {
49	        Some(at) => (&input[..at], &input[at..]),
50	        None => (input, ""),
51	    }
52	}
53	
54	/// Splits the raw authority at the **first** `'@'`, returning `(userinfo, host_port)`.
55	///
56	/// First — not last — which is why `"a@b:80@c:90"` has userinfo `"a"` and host
57	/// port text `"b:80@c:90"`, giving port `80`.
58	pub fn split_userinfo(authority: &str) -> (&str, &str) {
59	    match authority.find('@') {
60	        Some(at) => (&authority[..at], &authority[at + 1..]),
61	        None => ("", authority),
62	    }
63	}
64	
65	/// Splits the host/port text at the **first** `':'`, returning
66	/// `(host, port_text)`.
67	///
68	/// `port_text` is `None` when there is no colon at all, distinguishing "no port
69	/// was written" from "a port was written but did not convert".
70	pub fn split_host_port(host_port: &str) -> (&str, Option<&str>) {
71	    match host_port.find(':') {
72	        Some(at) => (&host_port[..at], Some(&host_port[at + 1..])),
73	        None => (host_port, None),
74	    }
75	}
76	
77	#[cfg(test)]
78	mod tests {
79	    use super::*;
80	
81	    #[test]
82	    fn fragment_and_query_take_the_first_delimiter() {
83	        assert_eq!(split_fragment("a#b#c"), ("a", "b#c"));
84	        assert_eq!(split_fragment("a?b#c"), ("a?b", "c"));
85	        assert_eq!(split_query("a?b?c"), ("a", "b?c"));
86	        assert_eq!(split_query("no-query"), ("no-query", ""));
87	    }
88	
89	    #[test]
90	    fn scheme_requires_the_full_separator() {
91	        assert_eq!(split_scheme("http://h"), Some(("http", "h")));
92	        assert_eq!(split_scheme("/a://b"), Some(("/a", "b")));
93	        assert_eq!(split_scheme("http:/h"), None);
94	        assert_eq!(split_scheme("http:h"), None);
95	    }
96	
97	    #[test]
98	    fn authority_stops_at_the_first_slash() {
99	        assert_eq!(split_authority_and_path("h/p/q"), ("h", "/p/q"));
100	        assert_eq!(split_authority_and_path("h"), ("h", ""));
101	        assert_eq!(split_authority_and_path("/p"), ("", "/p"));
102	    }
103	
104	    #[test]
105	    fn userinfo_and_port_use_first_delimiters() {
106	        assert_eq!(split_userinfo("a@b:80@c:90"), ("a", "b:80@c:90"));
107	        assert_eq!(split_userinfo("h:80@"), ("h:80", ""));
108	        assert_eq!(split_userinfo("h:80"), ("", "h:80"));
109	        assert_eq!(split_host_port("a:b:c"), ("a", Some("b:c")));
110	        assert_eq!(split_host_port("h"), ("h", None));
111	        assert_eq!(split_host_port("h:"), ("h", Some("")));
112	    }
113	}
